(3069877, 431108, 49963, '<td valign="top">Wooo gosh thank god your not my doctor! Great idea and well executed</td>', 'Wooo gosh thank god your not my doctor! Great idea and well executed', '2006-11-29 00:15:47.000000', NULL, 1),
