(3092400, 432881, 30861, '<td valign="top">Hey, good for you! First ribbon, personal best by a huge amount! We had a "temporary memorial" like this at Wellfleet on Cape Cod about a month ago, it was very moving.</td>', 'Hey, good for you! First ribbon, personal best by a huge amount! We had a "temporary memorial" like this at Wellfleet on Cape Cod about a month ago, it was very moving.', '2006-12-06 10:40:55.000000', NULL, 0),
(3092405, 432140, 30861, '<td valign="top">Well, you''re on a roll these past couple weeks :-) Congrats! Funny shot.</td>', 'Well, you''re on a roll these past couple weeks :-) Congrats! Funny shot.', '2006-12-06 10:42:33.000000', NULL, 0),
