(3093327, 432458, 50695, '<td valign="top">I thought this was so pretty. I''m glad to hear how it was done. I gave it a 9.</td>', 'I thought this was so pretty. I''m glad to hear how it was done. I gave it a 9.', '2006-12-06 15:15:08.000000', NULL, 0),
(3093331, 430870, 50695, '<td valign="top">I thought the combination of angel and background was a beautiful work of art. Truly lovely. I gave it a 9.</td>', 'I thought the combination of angel and background was a beautiful work of art. Truly lovely. I gave it a 9.', '2006-12-06 15:17:02.000000', NULL, 0),
(3093337, 431687, 50695, '<td valign="top">There is something so classical about that pose, like a Michelangelo or a Tiepolo. I gave this an 8 and probably would have gone higher if I''d gotten a chance to bump.</td>', 'There is something so classical about that pose, like a Michelangelo or a Tiepolo. I gave this an 8 and probably would have gone higher if I''d gotten a chance to bump.', '2006-12-06 15:19:00.000000', NULL, 0),
